function flashScreen(ms=260){ let el=document.querySelector('.flash-overlay'); if(!el){el=document.createElement('div'); el.className='flash-overlay'; document.body.appendChild(el);} el.animate([{opacity:0},{opacity:.95,offset:.35},{opacity:0}], {duration:ms,easing:'ease-out'}); }
function fadeTo(url, ms=420){ let el=document.querySelector('.fade-overlay'); if(!el){el=document.createElement('div'); el.className='fade-overlay'; document.body.appendChild(el);} const anim=el.animate([{opacity:0},{opacity:1}], {duration:ms,fill:'forwards',easing:'ease'}); anim.onfinish=()=>{location.href=url;}; }
function oneTimeScan(){ let el=document.querySelector('.scanline-layer'); if(!el){el=document.createElement('div'); el.className='scanline-layer'; document.body.appendChild(el);} el.animate([{opacity:0},{opacity:.75,offset:.25},{opacity:0}], {duration:850,easing:'linear'}); }
